-- stochastic-processes implementation for EnsembleKalman
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))
local VectorForge = ReplicatedStorage:WaitForChild("VectorForge")
local LA = require(VectorForge:WaitForChild("SpectralLinearAlgebra"))

local Module = {}
function Module.Analysis(ensemble,observations,H,R)
    local members=#ensemble; assert(members>=2,"EnKF needs at least two ensemble members")
    local stateDim=#ensemble[1]; local obsDim=#observations
    local mean=table.create(stateDim,0); local predicted={}
    for m=1,members do
        assert(#ensemble[m]==stateDim,"ensemble member dimension mismatch")
        local y=LA.MatrixVector(H,ensemble[m]); predicted[m]=y
        for i=1,stateDim do mean[i]+=ensemble[m][i]/members end
    end
    local yMean=table.create(obsDim,0); for m=1,members do for j=1,obsDim do yMean[j]+=predicted[m][j]/members end end
    local Pxy=LA.Zeros(stateDim,obsDim); local Pyy=LA.Copy(R)
    for m=1,members do
        local dx=Num.Subtract(ensemble[m],mean); local dy=Num.Subtract(predicted[m],yMean)
        Pxy=Num.Add(Pxy,Num.Scale(LA.Outer(dx,dy),1/(members-1)))
        Pyy=Num.Add(Pyy,Num.Scale(LA.Outer(dy,dy),1/(members-1)))
    end
    local Kgain=LA.Multiply(Pxy,LA.Inverse(Pyy)); local analyzed=table.create(members)
    for m=1,members do analyzed[m]=Num.Add(ensemble[m],LA.MatrixVector(Kgain,Num.Subtract(observations,predicted[m]))) end
    return analyzed,{Gain=Kgain,PredictedMean=yMean}
end

return Module
